changeSet.sql:
ALTER TABLE log_entry ADD COLUMN model_name text;
ALTER TABLE log_entry_hourly_stats ADD COLUMN model_name text;

CREATE FUNCTION logos_model_delete_backfill_name()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_catalog
AS $$
BEGIN
    UPDATE log_entry SET model_name = OLD.name WHERE model_id = OLD.id;
    RETURN OLD;
END;
$$;

CREATE TRIGGER trg_models_delete_backfill_model_name
    BEFORE DELETE ON models
    FOR EACH ROW
    EXECUTE FUNCTION logos_model_delete_backfill_name();

DROP INDEX ux_log_entry_hourly_stats_grain;
CREATE UNIQUE INDEX ux_log_entry_hourly_stats_grain ON log_entry_hourly_stats (bucket_hour, model_id, model_name, provider_id, team_id, user_id, result_status, was_cold_start) NULLS NOT DISTINCT;
CREATE OR REPLACE FUNCTION logos_stats_rollup_apply(p_hours timestamptz[]) RETURNS bigint LANGUAGE plpgsql SET search_path = public, pg_catalog AS $$ DECLARE affected bigint; BEGIN IF p_hours IS NULL OR array_length(p_hours, 1) IS NULL THEN RETURN 0; END IF;
DELETE FROM log_entry_hourly_stats s WHERE s.bucket_hour = ANY (p_hours);
INSERT INTO log_entry_hourly_stats ( bucket_hour, model_id, model_name, provider_id, team_id, user_id, result_status, was_cold_start, requests, queue_seconds_sum, queue_seconds_count, run_seconds_sum, run_seconds_count, error_count, total_tokens, cost_micro_cents) SELECT date_trunc('hour', COALESCE(le.timestamp_forwarding, le.timestamp_request, le.timestamp_response)), le.model_id, CASE WHEN le.model_id IS NULL THEN le.model_name END, le.provider_id, le.team_id, le.user_id, le.result_status, COALESCE(le.was_cold_start, FALSE), COUNT(*), SUM(CASE WHEN le.timestamp_request IS NOT NULL AND le.timestamp_forwarding IS NOT NULL THEN EXTRACT(EPOCH FROM (le.timestamp_forwarding - le.timestamp_request)) END), COUNT(*) FILTER (WHERE le.timestamp_request IS NOT NULL AND le.timestamp_forwarding IS NOT NULL), SUM(CASE WHEN le.timestamp_forwarding IS NOT NULL AND le.timestamp_response IS NOT NULL THEN EXTRACT(EPOCH FROM (le.timestamp_response - le.timestamp_forwarding)) END), COUNT(*) FILTER (WHERE le.timestamp_forwarding IS NOT NULL AND le.timestamp_response IS NOT NULL), COUNT(*) FILTER (WHERE le.result_status IS DISTINCT FROM 'success' OR (le.error_message IS NOT NULL AND le.error_message <> '')), COALESCE(SUM(tok.total_tokens), 0)::bigint, COALESCE(SUM(lec.cost_micro_cents), 0)::bigint FROM log_entry le LEFT JOIN LATERAL ( SELECT SUM(ut.token_count) AS total_tokens FROM usage_tokens ut JOIN token_types tt ON tt.id = ut.type_id WHERE ut.log_entry_id = le.id AND tt.name = 'total_tokens' ) tok ON TRUE LEFT JOIN log_entry_cost lec ON lec.log_entry_id = le.id WHERE date_trunc('hour', COALESCE(le.timestamp_forwarding, le.timestamp_request, le.timestamp_response)) = ANY (p_hours) GROUP BY 1, 2, 3, 4, 5, 6, 7, 8;
GET DIAGNOSTICS affected = ROW_COUNT; RETURN affected; END; $$;

rollback.sql:
CREATE OR REPLACE FUNCTION logos_stats_rollup_apply(p_hours timestamptz[]) RETURNS bigint LANGUAGE plpgsql SET search_path = public, pg_catalog AS $$ DECLARE affected bigint; BEGIN IF p_hours IS NULL OR array_length(p_hours, 1) IS NULL THEN RETURN 0; END IF;
DELETE FROM log_entry_hourly_stats s WHERE s.bucket_hour = ANY (p_hours);
INSERT INTO log_entry_hourly_stats ( bucket_hour, model_id, provider_id, team_id, user_id, result_status, was_cold_start, requests, queue_seconds_sum, queue_seconds_count, run_seconds_sum, run_seconds_count, error_count, total_tokens, cost_micro_cents) SELECT date_trunc('hour', COALESCE(le.timestamp_forwarding, le.timestamp_request, le.timestamp_response)), le.model_id, le.provider_id, le.team_id, le.user_id, le.result_status, COALESCE(le.was_cold_start, FALSE), COUNT(*), SUM(CASE WHEN le.timestamp_request IS NOT NULL AND le.timestamp_forwarding IS NOT NULL THEN EXTRACT(EPOCH FROM (le.timestamp_forwarding - le.timestamp_request)) END), COUNT(*) FILTER (WHERE le.timestamp_request IS NOT NULL AND le.timestamp_forwarding IS NOT NULL), SUM(CASE WHEN le.timestamp_forwarding IS NOT NULL AND le.timestamp_response IS NOT NULL THEN EXTRACT(EPOCH FROM (le.timestamp_response - le.timestamp_forwarding)) END), COUNT(*) FILTER (WHERE le.timestamp_forwarding IS NOT NULL AND le.timestamp_response IS NOT NULL), COUNT(*) FILTER (WHERE le.result_status IS DISTINCT FROM 'success' OR (le.error_message IS NOT NULL AND le.error_message <> '')), COALESCE(SUM(tok.total_tokens), 0)::bigint, COALESCE(SUM(lec.cost_micro_cents), 0)::bigint FROM log_entry le LEFT JOIN LATERAL ( SELECT SUM(ut.token_count) AS total_tokens FROM usage_tokens ut JOIN token_types tt ON tt.id = ut.type_id WHERE ut.log_entry_id = le.id AND tt.name = 'total_tokens' ) tok ON TRUE LEFT JOIN log_entry_cost lec ON lec.log_entry_id = le.id WHERE date_trunc('hour', COALESCE(le.timestamp_forwarding, le.timestamp_request, le.timestamp_response)) = ANY (p_hours) GROUP BY 1, 2, 3, 4, 5, 6, 7;
GET DIAGNOSTICS affected = ROW_COUNT; RETURN affected; END; $$;

DROP INDEX ux_log_entry_hourly_stats_grain;

CREATE UNIQUE INDEX ux_log_entry_hourly_stats_grain
    ON log_entry_hourly_stats (bucket_hour, model_id, provider_id, team_id,
                               user_id, result_status, was_cold_start)
    NULLS NOT DISTINCT;

changeSet.sql:
SELECT logos_stats_rollup_apply(ARRAY(
    SELECT DISTINCT date_trunc('hour', COALESCE(le.timestamp_forwarding,
                                                le.timestamp_request,
                                                le.timestamp_response))
    FROM log_entry le
    WHERE COALESCE(le.timestamp_forwarding, le.timestamp_request, le.timestamp_response)
          < date_trunc('hour', now())
));

ANALYZE log_entry_hourly_stats;

